  suspended Boolean

  /// Whether the seller is banned from logging in and using the platform.
  banned Boolean

  /// When this seller account was created.
  created_at DateTime @db.Timestamptz

  /// When this seller account was last updated.
  updated_at DateTime @db.Timestamptz

  /// When this seller account was soft deleted, preserving historical
  /// references after account deletion.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
