  passwordResets shopping_mall_seller_password_resets[]
  profile shopping_mall_seller_profiles?
  approvalRequests shopping_mall_seller_approval_requests[]
  administratorRequestApplications shopping_mall_administrator_request_of_sellers[]
  products shopping_mall_products[]
  orderItems shopping_mall_order_items[]
  shipments shopping_mall_shipments[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([approval_status, created_at])
