/// Seller-owned product listings that define the current sellable catalog
/// record for marketplace browsing and purchase preparation.
///
/// Each product stores the seller-controlled merchandise identity, current
/// category assignment, current base price, and lifecycle status used to
/// determine listing visibility and operational availability. The product is
/// the parent record for {@link shopping_mall_product_images}, {@link
/// shopping_mall_product_variants}, and {@link
/// shopping_mall_product_snapshots}, while search result enrichments such as
/// rating averages or price ranges are intentionally derived outside this
/// table to preserve normalization.
///
/// @namespace Catalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_products {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner seller account's {@link shopping_mall_sellers.id}.
  shopping_mall_seller_id String @db.Uuid

  /// Current assigned category's {@link shopping_mall_categories.id}. Nullable
  /// when the product becomes uncategorized after category deletion.
  shopping_mall_category_id String? @db.Uuid

  /// Current product name shown in catalog listings and detail pages.
  name String

  /// Current seller-provided product description shown on the detail page.
  description String

  /// Current base merchandise price before any variant-level price override is
  /// applied.
  base_price Float @db.DoublePrecision

  /// Current product lifecycle and listing state such as active, hidden, or
  /// deleted, used to enforce search visibility and purchase availability
  /// policies.
  status String

  /// When the product listing was first created.
  created_at DateTime @db.Timestamptz

  /// When the current product record was last updated.
  updated_at DateTime @db.Timestamptz

  /// When the product was soft-deleted from active listings while preserving
  /// historical references.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  seller   shopping_mall_sellers     @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade)
  category shopping_mall_categories? @relation(fields: [shopping_mall_category_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  images            shopping_mall_product_images[]
  variants          shopping_mall_product_variants[]
  snapshots         shopping_mall_product_snapshots[]
  wishlistEntries   shopping_mall_wishlist_entries[]
  cartItems         shopping_mall_cart_items[]
  purchaseSnapshots shopping_mall_product_purchase_snapshots[]
  reviews           shopping_mall_reviews[]

  //----
  // INDEXES
  //----
  @@index([shopping_mall_seller_id, created_at])
  @@index([shopping_mall_category_id, created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Ordered gallery images belonging to a product listing.
///
/// This table stores each active or soft-deleted gallery image for a single
/// {@link shopping_mall_products} record, including its resource URI,
/// product-scoped display order, and whether it is the current thumbnail
/// image. Product image lifecycle is managed through the parent product,
/// while immutable historical image state is preserved separately in {@link
/// shopping_mall_product_snapshot_image_copies} during product snapshot
/// creation.
///
/// The design keeps one row per image to satisfy normalization and supports
/// seller-driven reordering, thumbnail selection, and removal without
/// duplicating product or seller data.
///
/// @namespace Catalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_product_images {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged product's {@link shopping_mall_products.id}.
  shopping_mall_product_id String @db.Uuid

  /// Stored resource location of the product gallery image.
  image_uri String @db.VarChar(80000)

  /// Product-scoped display order of the image; the lowest sequence appears
  /// first in the gallery.
  sequence Int @db.Integer

  /// Whether this image is the current thumbnail shown as the primary product
  /// image.
  is_thumbnail Boolean

  /// When this product image record was created.
  created_at DateTime @db.Timestamptz

  /// When this product image record was last updated.
  updated_at DateTime @db.Timestamptz

  /// When this product image was soft-deleted; null means the image is
  /// currently active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  product shopping_mall_products @relation(fields: [shopping_mall_product_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@unique([shopping_mall_product_id, sequence], map: "shopping_mall_product_images_shopping_mall_product_id__35b7f07f")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_product_id, deleted_at, sequence], map: "shopping_mall_product_images_shopping_mall_product_id__09d31328")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_product_id, deleted_at, is_thumbnail], map: "shopping_mall_product_images_shopping_mall_product_id__e0b93ccb")
}

/// Purchasable SKU-level variants belonging to a product.
///
/// This table stores the seller-managed variant identity and commercial
/// option combination for a {@link shopping_mall_products} record, including
/// its required SKU code, human-readable option combination, and optional
/// price override relative to the product base price. It is the canonical
/// source referenced by cart items, order items, inventory history, and
/// variant snapshot records.
///
/// Current stock is not stored in this table because inventory must be
/// derived from immutable {@link shopping_mall_inventory_records} rows.
/// Historical edits are preserved separately in {@link
/// shopping_mall_product_variant_snapshots}, keeping this table focused on
/// the active mutable variant state.
///
/// @namespace Catalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_product_variants {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent product's {@link shopping_mall_products.id}.
  shopping_mall_product_id String @db.Uuid

  /// Seller-managed SKU identifier for this purchasable variant.
  sku_code String

  /// Human-readable atomic description of the variant option combination, such
  /// as "Red / Large".
  option_summary String

  /// Optional variant-specific selling price override; when null, the parent
  /// product base price is used.
  price Float? @db.DoublePrecision

  /// When this variant was created.
  created_at DateTime @db.Timestamptz

  /// When this variant was last updated.
  updated_at DateTime @db.Timestamptz

  /// When this variant was soft deleted. Null means the variant is active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  product shopping_mall_products @relation(fields: [shopping_mall_product_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  inventoryRecords  shopping_mall_inventory_records[]
  snapshots         shopping_mall_product_variant_snapshots[]
  cartItems         shopping_mall_cart_items[]
  orderItems        shopping_mall_order_items[]
  purchaseSnapshots shopping_mall_product_purchase_snapshots[]

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@unique([shopping_mall_product_id, sku_code], map: "shopping_mall_product_variants_shopping_mall_product_i_275bf3f1")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_product_id, created_at], map: "shopping_mall_product_variants_shopping_mall_product_i_8fcece9d")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_product_id, deleted_at], map: "shopping_mall_product_variants_shopping_mall_product_i_8c145443")
  @@index([sku_code(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([option_summary(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Immutable stock movement ledger entries for a product variant.
///
/// Each record captures one atomic inventory change such as restocking,
/// manual adjustment, order placement, cancellation restoration, refund
/// restoration, or administrative correction. The current stock quantity is
/// derived by summing signed changes across records rather than storing a
/// mutable balance.
///
/// This table belongs to {@link shopping_mall_product_variants} and supports
/// audit-friendly inventory tracing for sellers and administrators without
/// duplicating catalog or order data.
///
/// @namespace Catalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_inventory_records {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged product variant's {@link shopping_mall_product_variants.id}.
  shopping_mall_product_variant_id String @db.Uuid

  /// Signed inventory delta applied by this ledger entry. Positive values
  /// increase stock and negative values decrease stock.
  quantity_change Int @db.Integer

  /// Business reason describing why the inventory changed, such as restock,
  /// order placement, cancellation restoration, refund restoration, manual
  /// loss adjustment, or administrative correction.
  reason String

  /// Business timestamp when the stock movement occurred and should be counted
  /// in the inventory ledger.
  occurred_at DateTime @db.Timestamptz

  /// Timestamp when this inventory record was stored.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this record metadata was last updated. In normal business
  /// use, immutable inventory entries should not be edited.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. This should remain null in normal business use
  /// because inventory records are intended to be preserved for audit history.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
  productVariant shopping_mall_product_variants @relation(fields: [shopping_mall_product_variant_id], references: [id], onDelete: Cascade, map: "shopping_mall_inventory_records_shopping_mall_product__77c94f83")

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([shopping_mall_product_variant_id, created_at], map: "shopping_mall_inventory_records_shopping_mall_product__00896e55")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_product_variant_id, occurred_at], map: "shopping_mall_inventory_records_shopping_mall_product__9e0f7ef3")
}

