  TestValidator.predicate(
    "review note search rows match searchable text",
    reviewNoteSearchPage.data.every(
      (row) =>
        row.reason.includes(approvalReviewNote) ||
        (row.reviewNote !== null &&
          row.reviewNote.includes(approvalReviewNote)) ||
