export async function test_api_product_image_gallery_update_success(
  connection: api.IConnection,
): Promise<void> {
  const sellerConnection: api.IConnection = {
    host: connection.host,
  };
  const seller = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    },
  });
  typia.assert(seller);
  const created =
    await generate_random_shopping_mall_seller_seller_products_create(
      sellerConnection,
      {
        body: {
          shopping_mall_category_id: null,
          name: RandomGenerator.name(),
          description: RandomGenerator.content({ paragraphs: 2 }),
          base_price: typia.random<number & tags.Minimum<1>>() satisfies number,
          status: RandomGenerator.pick(["draft", "active", "selling"] as const),
        },
      },
    );
  typia.assert(created);
  const previousUpdatedAt: string = created.updated_at;
  const request = {
    imageUri: typia.random<string & tags.Format<"uri">>(),
    sequence: typia.random<number & tags.Type<"int32">>(),
    isThumbnail: false,
  } satisfies IShoppingMallProductImage.IUpdate;
  const updated = await api.functional.shoppingMall.products.images.update(
    sellerConnection,
    {
      productId: created.id,
      body: request,
    },
  );
  typia.assert(updated);
  TestValidator.equals("product id is preserved", updated.id, created.id);
  TestValidator.equals("seller id is preserved", updated.seller.id, seller.id);
  TestValidator.notEquals(
    "product updated_at changes after image edit",
    updated.updated_at,
    previousUpdatedAt,
  );
  const sortedImages = [...updated.images].sort(
    (x, y) => x.sequence - y.sequence,
  );
  TestValidator.equals(
    "images are returned in ascending sequence order",
    updated.images.map((image) => image.id),
    sortedImages.map((image) => image.id),
  );
  updated.images.forEach((image) => {
    TestValidator.equals(
      "each image belongs to the updated product",
      image.product.id,
      updated.id,
    );
  });
  const thumbnailImages = updated.images.filter((image) => image.is_thumbnail);
  if (updated.images.length > 0) {
    TestValidator.equals(
      "exactly one effective thumbnail exists",
      thumbnailImages.length,
      1,
    );
    TestValidator.equals(
      "first image is the thumbnail used for listing purposes",
      updated.images[0]!.is_thumbnail,
      true,
    );
  } else {
    TestValidator.equals(
      "no thumbnail exists when gallery is empty",
      thumbnailImages.length,
      0,
    );
  }
}

