export async function test_api_product_variant_list_owned_product_filters(
  connection: api.IConnection,
): Promise<void> {
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    },
  });
  typia.assert(seller);
  const targetProduct =
    await generate_random_shopping_mall_seller_seller_products_create(
      sellerConnection,
      {
        body: {
          shopping_mall_category_id: null,
          name: `Target Product ${RandomGenerator.name(2)}`,
          description: RandomGenerator.content({ paragraphs: 2 }),
          base_price: 15000,
          status: "active",
        },
      },
    );
  typia.assert(targetProduct);
  const otherProduct =
    await generate_random_shopping_mall_seller_seller_products_create(
      sellerConnection,
      {
        body: {
          shopping_mall_category_id: null,
          name: `Other Product ${RandomGenerator.name(2)}`,
          description: RandomGenerator.content({ paragraphs: 2 }),
          base_price: 18000,
          status: "active",
        },
      },
    );
  typia.assert(otherProduct);
  const scopeKey = RandomGenerator.alphabets(8);
  const targetNullVariant =
    await generate_random_shopping_mall_seller_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: targetProduct.id },
        body: {
          sku_code: `TARGET-${scopeKey}-A`,
          option_summary: `Scope ${scopeKey} Alpha`,
          price: null,
        },
      },
    );
  typia.assert(targetNullVariant);
  const targetPricedVariant =
    await generate_random_shopping_mall_seller_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: targetProduct.id },
        body: {
          sku_code: `TARGET-${scopeKey}-B`,
          option_summary: `Scope ${scopeKey} Beta`,
          price: 21900,
        },
      },
    );
  typia.assert(targetPricedVariant);
  const targetExtraVariant =
    await generate_random_shopping_mall_seller_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: targetProduct.id },
        body: {
          sku_code: `TARGET-${scopeKey}-C`,
          option_summary: `Scope ${scopeKey} Gamma`,
          price: 19900,
        },
      },
    );
  typia.assert(targetExtraVariant);
  const leakedCandidateVariant =
    await generate_random_shopping_mall_seller_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: otherProduct.id },
        body: {
          sku_code: `TARGET-${scopeKey}-Z`,
          option_summary: `Scope ${scopeKey} Outside`,
          price: 17500,
        },
      },
    );
  typia.assert(leakedCandidateVariant);
  const filteredPage =
    await api.functional.shoppingMall.products.variants.index(
      sellerConnection,
      {
        productId: targetProduct.id,
        body: {
          search: scopeKey,
          deletedAt: null,
          sort: "skuCode",
          direction: "asc",
          page: 1,
          limit: 10,
        } satisfies IShoppingMallProductVariant.IRequest,
      },
    );
  typia.assert(filteredPage);
  TestValidator.equals(
    "filtered page current page matches request",
    filteredPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "filtered page limit matches request",
    filteredPage.pagination.limit,
    10,
  );
  TestValidator.predicate(
    "filtered page size does not exceed limit",
    filteredPage.data.length <= filteredPage.pagination.limit,
  );
  TestValidator.predicate(
    "filtered page record count covers returned rows",
    filteredPage.pagination.records >= filteredPage.data.length,
  );
  TestValidator.equals(
    "filtered page count metadata is consistent",
    filteredPage.pagination.pages,
    filteredPage.pagination.records === 0
      ? 0
      : Math.ceil(
          filteredPage.pagination.records / filteredPage.pagination.limit,
        ),
  );
  TestValidator.equals(
    "search scoped result count excludes other product variant",
    filteredPage.data.length,
    3,
  );
  TestValidator.equals(
    "first sorted sku is target null variant",
    filteredPage.data[0]?.sku_code,
    targetNullVariant.sku_code,
  );
  TestValidator.equals(
    "second sorted sku is target priced variant",
    filteredPage.data[1]?.sku_code,
    targetPricedVariant.sku_code,
  );
  TestValidator.equals(
    "third sorted sku is target extra variant",
    filteredPage.data[2]?.sku_code,
    targetExtraVariant.sku_code,
  );
  TestValidator.predicate(
    "other product variant is not leaked into scoped search results",
    filteredPage.data.every(
      (variant) => variant.id !== leakedCandidateVariant.id,
    ),
  );
  const nullPriceSummary = filteredPage.data.find(
    (variant) => variant.id === targetNullVariant.id,
  );
  TestValidator.equals(
    "null override price is preserved in summary",
    nullPriceSummary?.price,
    null,
  );
  TestValidator.equals(
    "null override sku is preserved",
    nullPriceSummary?.sku_code,
    targetNullVariant.sku_code,
  );
  TestValidator.equals(
    "null override option summary is preserved",
    nullPriceSummary?.option_summary,
    targetNullVariant.option_summary,
  );
  TestValidator.equals(
    "null override created_at is preserved",
    nullPriceSummary?.created_at,
    targetNullVariant.created_at,
  );
  TestValidator.equals(
