  );
  TestValidator.equals(
    "null-price detail parent product id matches",
    nullPriceDetail.product.id,
    product.id,
  );
  TestValidator.equals(
    "null-price detail parent product seller id matches owner",
    nullPriceDetail.product.seller.id,
    product.seller.id,
