    "same seller email",
    updated.seller.email,
    created.seller.email,
  );
  TestValidator.equals("updated name", updated.name, updateBody.name);
  TestValidator.equals(
    "updated description",
    updated.description,
    updateBody.description,
  );
  TestValidator.equals(
    "updated base price",
    updated.base_price,
    updateBody.base_price,
  );
  TestValidator.equals("updated status", updated.status, updateBody.status);
  TestValidator.equals("category cleared", updated.category, null);
  TestValidator.equals(
    "created_at preserved",
    updated.created_at,
    created.created_at,
  );
  TestValidator.equals(
    "deleted_at preserved",
    updated.deleted_at,
    created.deleted_at,
  );
  TestValidator.equals("images preserved", updated.images, created.images);
  TestValidator.equals(
    "variants preserved",
    updated.variants,
    created.variants,
  );
  TestValidator.notEquals(
    "updated_at changes after update",
    updated.updated_at,
    created.updated_at,
  );
  TestValidator.equals(
    "authorized seller remains owner",
    updated.seller.id,
    authorized.id,
  );
}

