    "non-owner seller cannot update another seller's product image",
    403,
    async () => {
      await api.functional.shoppingMall.seller.seller_products.images.putByProductidAndImageid(
        intruderConnection,
        {
          productId: product.id,
          imageId: image.id,
          body: updateBody,
        },
      );
