    "image sequence remains unchanged in captured state",
    createdImage.sequence,
    originalSequence,
  );
  TestValidator.equals(
    "image thumbnail flag remains unchanged in captured state",
    createdImage.is_thumbnail,
    originalThumbnail,
  );
}

