      sellerConnection,
      {
        params: {
          productId: product.id,
        },
        body: {
          sku_code: `sku-${RandomGenerator.alphaNumeric(8)}`,
          option_summary: `${RandomGenerator.name(1)} / ${RandomGenerator.name(1)}`,
          price: null,
