    variant.id,
  );
  TestValidator.notEquals(
    "inventory record creates a distinct ledger entry id",
    inventoryRecord.id,
    variant.id,
  );
  TestValidator.predicate(
    "inventory record represents a manual reduction with a negative delta",
    inventoryRecord.quantity_change < 0,
  );
}

