  const order = typia.assert(maybeOrder);
  const orderItems =
    await api.functional.shoppingMall.customer.orders.items.index(
      customerConnection,
      {
        orderId: order.id,
        body: {
          page: 1,
          limit: 100,
        },
      },
    );
