  const snapshotBody = {
    shop_name: `shop-${RandomGenerator.name(2)}`,
    logo_uri: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallSellerProfilePurchaseSnapshot.ICreate;
