    await generate_random_shopping_mall_customer_orders_items_product_purchase_snapshots_create(
      customerConnection,
      {
        params: {
          orderId,
          itemId: validItemId,
        },
        body: snapshotBody,
      },
    );
  typia.assert(snapshot);
  TestValidator.equals(
    "snapshot belongs to requested item",
    snapshot.orderItem.id,
    validItemId,
