  >(toISOStringSafe(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)));
  const sessionId: string & tags.Format<"uuid"> = typia.assert<
    string & tags.Format<"uuid">
  >(v4());
  await MyGlobal.prisma.shopping_mall_administrator_sessions.create({
    data: {
      id: sessionId,
      administrator: {
        connect: {
