import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { ShoppingMallSellerTransformer } from "../transformers/ShoppingMallSellerTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postShoppingMallAuthSellerRefresh(props: {
  body: IShoppingMallSeller.IRefresh;
}): Promise<IShoppingMallSeller.IAuthorized> {
  const unauthorized = (): never => {
    throw new HttpException("Invalid or expired refresh token", 401);
  };
  const forbidden = (message: string): never => {
    throw new HttpException(message, 403);
  };
  const verifiedUnknown: unknown = (() => {
    try {
      return jwt.verify(props.body.refresh, MyGlobal.env.JWT_SECRET_KEY, {
        issuer: "autobe",
      });
    } catch {
      unauthorized();
    }
  })();
  if (typeof verifiedUnknown !== "object" || verifiedUnknown === null)
    unauthorized();
  const verifiedObject = verifiedUnknown as {
    type?: unknown;
    id?: unknown;
    session_id?: unknown;
  };
  if (verifiedObject.type !== "seller") unauthorized();
  const verifiedId: string =
    typeof verifiedObject.id === "string" ? verifiedObject.id : unauthorized();
  const verifiedSessionId: string =
    typeof verifiedObject.session_id === "string"
      ? verifiedObject.session_id
      : unauthorized();
  const verified: {
    type: "seller";
    id: string;
    session_id: string;
  } = {
    type: "seller",
    id: verifiedId,
    session_id: verifiedSessionId,
  };
  const session = await MyGlobal.prisma.shopping_mall_seller_sessions.findFirst(
    {
      where: {
        id: verified.session_id,
        shopping_mall_seller_id: verified.id,
      },
      select: {
        id: true,
        shopping_mall_seller_id: true,
        expired_at: true,
      },
    },
  );
  const sessionRecord = session === null ? unauthorized() : session;
  if (sessionRecord.expired_at.getTime() <= globalThis.Date.now())
    unauthorized();
  const seller = await MyGlobal.prisma.shopping_mall_sellers.findUniqueOrThrow({
    where: {
      id: verified.id,
    },
    ...ShoppingMallSellerTransformer.select(),
  });
  if (seller.banned === true) forbidden("Seller is banned");
  if (seller.deleted_at !== null) forbidden("Seller account has been deleted");
  const now: string & tags.Format<"date-time"> = toISOStringSafe(
    new globalThis.Date(),
  );
  const accessExpiredAt: string & tags.Format<"date-time"> = toISOStringSafe(
    new globalThis.Date(globalThis.Date.now() + 60 * 60 * 1000),
  );
  const refreshableUntil: string & tags.Format<"date-time"> = toISOStringSafe(
    new globalThis.Date(globalThis.Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const access: string = jwt.sign(
    {
      type: "seller",
      id: verified.id,
      session_id: verified.session_id,
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      issuer: "autobe",
      expiresIn: "1h",
    },
  );
  const refresh: string = jwt.sign(
    {
      type: "seller",
      id: verified.id,
      session_id: verified.session_id,
      created_at: now,
      token_type: "refresh",
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      issuer: "autobe",
      expiresIn: "7d",
    },
  );
  await MyGlobal.prisma.shopping_mall_seller_sessions.update({
    where: {
      id: sessionRecord.id,
    },
    data: {
      expired_at: new globalThis.Date(refreshableUntil),
    },
  });
  return {
    ...(await ShoppingMallSellerTransformer.transform(seller)),
    token: {
      access,
      refresh,
      expired_at: accessExpiredAt,
      refreshable_until: refreshableUntil,
    },
  };
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { SellerPayload } from "../decorators/payload/SellerPayload";
import { ShoppingMallProductTransformer } from "../transformers/ShoppingMallProductTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function putShoppingMallSellerSellerProductsProductId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  body: IShoppingMallProduct.IUpdate;
}): Promise<IShoppingMallProduct> {
  const now = toISOStringSafe(new globalThis.Date());
  return await MyGlobal.prisma.$transaction(async (tx) => {
    const product = await tx.shopping_mall_products.findUniqueOrThrow({
      where: { id: props.productId },
      select: {
        id: true,
        shopping_mall_seller_id: true,
        deleted_at: true,
      },
    });
    if (product.deleted_at !== null) {
      throw new HttpException("Product not found", 404);
    }
    if (product.shopping_mall_seller_id !== props.seller.id) {
      throw new HttpException("Forbidden", 403);
    }
    if (
      props.body.shopping_mall_category_id !== undefined &&
      props.body.shopping_mall_category_id !== null
    ) {
      const category = await tx.shopping_mall_categories.findUnique({
        where: { id: props.body.shopping_mall_category_id },
        select: {
          id: true,
          deleted_at: true,
        },
      });
      if (category === null || category.deleted_at !== null) {
        throw new HttpException("Invalid category reference", 400);
      }
    }
    try {
      const snapshot = await tx.shopping_mall_product_snapshots.create({
        data: {
          id: v4(),
          product: {
            connect: {
              id: props.productId,
            },
          },
          created_at: now,
        },
        select: {
          id: true,
        },
      });
      const images = await tx.shopping_mall_product_images.findMany({
        where: {
          shopping_mall_product_id: props.productId,
          deleted_at: null,
        },
        select: {
          id: true,
          image_uri: true,
          sequence: true,
          is_thumbnail: true,
        },
        orderBy: {
          sequence: "asc",
        },
      });
      for (const image of images) {
        await tx.shopping_mall_product_snapshot_image_copies.create({
          data: {
            id: v4(),
            productSnapshot: {
              connect: {
                id: snapshot.id,
              },
            },
            image_uri: image.image_uri,
            sequence: image.sequence,
            thumbnail: image.is_thumbnail,
            created_at: now,
          },
        });
      }
      const variants = await tx.shopping_mall_product_variants.findMany({
        where: {
          shopping_mall_product_id: props.productId,
          deleted_at: null,
        },
        select: {
          id: true,
        },
      });
      for (const variant of variants) {
        await tx.shopping_mall_product_variant_snapshots.create({
          data: {
            id: v4(),
            productVariant: {
              connect: {
                id: variant.id,
              },
            },
            productSnapshot: {
              connect: {
                id: snapshot.id,
              },
            },
            change_summary: "Product variant snapshot created",
            created_at: now,
          },
        });
      }
    } catch {
      throw new HttpException("Product update could not be completed", 400);
    }
    await tx.shopping_mall_products.update({
      where: { id: props.productId },
      data: {
        ...(props.body.shopping_mall_category_id !== undefined
          ? {
              category:
                props.body.shopping_mall_category_id === null
                  ? { disconnect: true }
                  : {
                      connect: {
                        id: props.body.shopping_mall_category_id,
                      },
                    },
            }
          : {}),
        ...(props.body.name !== undefined
          ? {
              name: props.body.name,
            }
          : {}),
        ...(props.body.description !== undefined
          ? {
              description: props.body.description,
            }
          : {}),
        ...(props.body.base_price !== undefined
          ? {
              base_price: props.body.base_price,
            }
          : {}),
        ...(props.body.status !== undefined
          ? {
              status: props.body.status,
            }
          : {}),
        updated_at: now,
      },
    });
    const updated = await tx.shopping_mall_products.findUniqueOrThrow({
      where: { id: props.productId },
      ...ShoppingMallProductTransformer.select(),
    });
    return await ShoppingMallProductTransformer.transform(updated);
  });
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postShoppingMallAuthCustomerJoin(props: {
  ip: string;
  body: IShoppingMallCustomer.IJoin;
}): Promise<IShoppingMallCustomer.IAuthorized> {
  const normalizedEmail: string & tags.Format<"email"> = typia.assert<
    string & tags.Format<"email">
  >(props.body.email.trim().toLowerCase());
  const existing = await MyGlobal.prisma.shopping_mall_customers.findFirst({
    where: {
      email: normalizedEmail,
    },
    select: {
      id: true,
    },
  });
  if (existing !== null) {
    throw new HttpException("Email already registered", 409);
  }
  const createdAt: string & tags.Format<"date-time"> = typia.assert<
    string & tags.Format<"date-time">
  >(new Date().toISOString());
  const expiredAt: string & tags.Format<"date-time"> = typia.assert<
    string & tags.Format<"date-time">
  >(new Date(Date.now() + 60 * 60 * 1000).toISOString());
  const refreshableUntil: string & tags.Format<"date-time"> = typia.assert<
    string & tags.Format<"date-time">
  >(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString());
  const customerId: string & tags.Format<"uuid"> = typia.assert<
    string & tags.Format<"uuid">
  >(v4());
  const sessionId: string & tags.Format<"uuid"> = typia.assert<
    string & tags.Format<"uuid">
  >(v4());
  const passwordHash: string = await PasswordUtil.hash(props.body.password);
  const ip: string = props.body.ip ?? props.ip;
  const result = await MyGlobal.prisma.$transaction(async (tx) => {
    const customer = await tx.shopping_mall_customers.create({
      data: {
        id: customerId,
        email: normalizedEmail,
        password_hash: passwordHash,
        banned_at: null,
        created_at: new Date(createdAt),
        updated_at: new Date(createdAt),
        deleted_at: null,
      },
      select: {
        id: true,
        email: true,
        banned_at: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    });
    const session = await tx.shopping_mall_customer_sessions.create({
      data: {
        id: sessionId,
        customer: {
          connect: {
            id: customer.id,
          },
        },
        ip,
        href: props.body.href,
        referrer: props.body.referrer,
        created_at: new Date(createdAt),
        expired_at: new Date(expiredAt),
      },
      select: {
        id: true,
      },
    });
    return {
      customer,
      session,
    };
  });
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "customer",
        id: result.customer.id,
        session_id: result.session.id,
        created_at: createdAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "customer",
        id: result.customer.id,
        session_id: result.session.id,
        tokenType: "refresh",
        created_at: createdAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: expiredAt,
    refreshable_until: refreshableUntil,
  };
  return {
    id: result.customer.id,
    email: result.customer.email,
    banned_at: result.customer.banned_at?.toISOString() ?? null,
    created_at: result.customer.created_at.toISOString(),
    updated_at: result.customer.updated_at.toISOString(),
    deleted_at: result.customer.deleted_at?.toISOString() ?? null,
    token,
  };
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
