    data: await ArrayUtil.asyncMap(
      rows,
      ShoppingMallSellerProfilePurchaseSnapshotTransformer.transform,
    ),
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
  };
}

