export async function postShoppingMallCustomerCancellationRequests(props: {
  customer: CustomerPayload;
  body: IShoppingMallCancellationRequest.ICreate;
}): Promise<IShoppingMallCancellationRequest> {
  const trimmedReason: string = props.body.reason.trim();
  if (trimmedReason.length === 0) {
    throw new HttpException("Reason is required", 400);
  }
  const orderItem =
    await MyGlobal.prisma.shopping_mall_order_items.findUniqueOrThrow({
      where: {
        id: props.body.shopping_mall_order_item_id,
      },
      select: {
        id: true,
        status: true,
        order: {
          select: {
            shopping_mall_customer_id: true,
          },
        },
      },
    });
  if (orderItem.order.shopping_mall_customer_id !== props.customer.id) {
    throw new HttpException("Forbidden", 403);
  }
  if (orderItem.status !== "paid") {
    throw new HttpException("Order item is not eligible for cancellation", 400);
  }
  const existing =
    await MyGlobal.prisma.shopping_mall_cancellation_requests.findUnique({
      where: {
        shopping_mall_order_item_id: props.body.shopping_mall_order_item_id,
      },
      select: {
        id: true,
      },
    });
  if (existing !== null) {
    throw new HttpException("Cancellation request already exists", 409);
  }
  const created =
    await MyGlobal.prisma.shopping_mall_cancellation_requests.create({
      data: await ShoppingMallCancellationRequestCollector.collect({
        body: {
          shopping_mall_order_item_id: props.body.shopping_mall_order_item_id,
          reason: trimmedReason,
        },
        customer: {
          id: props.customer.id,
        },
      }),
      ...ShoppingMallCancellationRequestTransformer.select(),
    });
  return await ShoppingMallCancellationRequestTransformer.transform(created);
}

